static void ms(uint32_t*a,uint32_t*tmp,size_t n){uint32_t*s=a,*d=tmp;int flip=0;for(size_t w=1;w<n;w*=2){for(size_t lo=0;lo<n;lo+=2*w){size_t mid=lo+w<n?lo+w:n,hi=lo+2*w<n?lo+2*w:n,i=lo,j=mid,k=lo;while(i<mid&&j<hi)d[k++]=s[i]<=s[j]?s[i++]:s[j++];while(i<mid)d[k++]=s[i++];while(j<hi)d[k++]=s[j++];}uint32_t*z=s;s=d;d=z;flip^=1;if(w>n/2)break;}if(flip)memcpy(a,s,n*4);}
