static void graph(uint32_t*a,uint32_t*w,size_t n,int d){for(size_t i=0;i<n;i++)for(int e=0;e<d;e++){size_t p=i*d+e;a[p]=e==0?(i+1)%n:e==1?(i+n-1)%n:mix32(p)%n;if(w)w[p]=1+(mix32(UINT32_C(0xabc00000)+(uint32_t)p)&15);}}
