struct HP{uint64_t d;uint32_t v;};
static void hpp(struct HP*h,size_t*sz,struct HP x){size_t i=(*sz)++;while(i){size_t p=(i-1)/2;if(h[p].d<=x.d)break;h[i]=h[p];i=p;}h[i]=x;}
