static uint32_t dijo(const uint32_t*a,const uint32_t*w,size_t n,int d,uint64_t*dist,struct HP*h){for(size_t i=0;i<n;i++)dist[i]=UINT64_MAX/4;size_t sz=0;dist[0]=0;hpp(h,&sz,(struct HP){0,0});while(sz){struct HP x=hpo(h,&sz);if(x.d!=dist[x.v])continue;for(int e=0;e<d;e++){size_t p=(size_t)x.v*d+e;uint32_t v=a[p];uint64_t nd=x.d+w[p];if(nd<dist[v]){dist[v]=nd;hpp(h,&sz,(struct HP){nd,v});}}}return ck64(dist,n);}
