static uint32_t uff(uint32_t*p,uint32_t x){while(p[x]!=x){p[x]=p[p[x]];x=p[x];}return x;}
static void ufo(uint32_t*p,uint8_t*rank,size_t n,const uint32_t*A,const uint32_t*B,size_t ops){for(size_t i=0;i<n;i++){p[i]=i;rank[i]=0;}for(size_t i=0;i<ops;i++){uint32_t ra=uff(p,A[i]),rb=uff(p,B[i]);if(ra!=rb){if(rank[ra]<rank[rb]){uint32_t z=ra;ra=rb;rb=z;}p[rb]=ra;if(rank[ra]==rank[rb])rank[ra]++;}}}
