static uint64_t mandel(int w,int mi){uint64_t s=0;for(int y=0;y<w;y++){double ci=-1.5+3.0*y/(w-1.0);for(int x=0;x<w;x++){double cr=-2+3.0*x/(w-1.0),zr=0,zi=0;int it=0;while(it<mi){double a=zr*zr,b=zi*zi;if(a+b>4)break;double nz=a-b+cr;zi=2*zr*zi+ci;zr=nz;it++;}s+=it;}}return s;}
