static uint32_t hto(uint32_t*k,uint32_t*v,size_t cap,const uint32_t*ink,const uint32_t*inv,size_t n){memset(k,0,cap*4);size_t mask=cap-1;uint32_t h=0;for(size_t i=0;i<n;i++){uint32_t key=ink[i],val=inv[i];size_t p=hash32(key)&mask;while(k[p]&&k[p]!=key)p=(p+1)&mask;k[p]=key;v[p]=val;}for(size_t i=0;i<n;i++){uint32_t key=ink[i];size_t p=hash32(key)&mask;while(k[p]!=key)p=(p+1)&mask;v[p]^=(uint32_t)i;h^=v[p];}return h;}
