static int bbst(uint64_t nu,int r){size_t n=nu;uint32_t*k=malloc(n*4),*in=malloc(n*4);int32_t*l=malloc(n*4),*rr=malloc(n*4);double*t=malloc(r*8);for(size_t i=0;i<n;i++)in[i]=mix32(i);uint32_t c=0;for(int x=0;x<r;x++){double s=now_s();c=bsto(k,l,rr,in,n);t[x]=now_s()-s;}double m=med(t,r);emit("bst",nu,r,m,n/(m*1e6),c);free(t);free(rr);free(l);free(in);free(k);return 0;}

static uint32_t tro(int32_t*ch,uint8_t*term,size_t mx,const uint32_t*words,size_t n,int passes){for(size_t i=0;i<mx*16;i++)ch[i]=-1;memset(term,0,mx);size_t used=1;for(size_t i=0;i<n;i++){uint32_t w=words[i];int32_t node=0;for(int sh=28;sh>=0;sh-=4){int c=(w>>sh)&15;int32_t*p=&ch[(size_t)node*16+c];if(*p<0)*p=used++;node=*p;}term[node]=1;}uint32_t h=used;for(int p=0;p<passes;p++)for(size_t i=0;i<n;i+=2){uint32_t w=words[i];int32_t node=0;for(int sh=28;sh>=0&&node>=0;sh-=4)node=ch[(size_t)node*16+((w>>sh)&15)];if(node>=0&&term[node])h^=(uint32_t)node+1+(uint32_t)p;}return h;}
static int btr(uint64_t nu,int r){const int p=32;size_t n=nu,mx=1+n*8;int32_t*ch=malloc(mx*16*4);uint8_t*term=malloc(mx);uint32_t*words=malloc(n*4);double*t=malloc(r*8);for(size_t i=0;i<n;i++)words[i]=mix32(i);uint32_t c=0;for(int x=0;x<r;x++){double s=now_s();c=tro(ch,term,mx,words,n,p);t[x]=now_s()-s;}double m=med(t,r);emit("trie",nu*p,r,m,n*p/(m*1e6),c);free(t);free(words);free(term);free(ch);return 0;}

static uint64_t ds(const char*k){if(!strcmp(k,"integer50"))return 200000000;if(!strcmp(k,"json_escape"))return 16000000;if(!strcmp(k,"merge_sort")||!strcmp(k,"binary_search")||!strcmp(k,"union_find")||!strcmp(k,"hash_table")||!strcmp(k,"binary_heap"))return 1000000;if(!strcmp(k,"prefix_sum"))return 8000000;if(!strcmp(k,"matrix_mul"))return 320;if(!strcmp(k,"bfs"))return 200000;if(!strcmp(k,"dijkstra")||!strcmp(k,"trie"))return 100000;if(!strcmp(k,"mandelbrot"))return 1600;if(!strcmp(k,"dynamic_array"))return 5000000;if(!strcmp(k,"linked_list"))return 4000000;if(!strcmp(k,"queue_ring"))return 10000000;if(!strcmp(k,"bst"))return 300000;return 0;}
static int run(const char*k,uint64_t n,int r){if(!strcmp(k,"integer50"))return bi(n,r);if(!strcmp(k,"json_escape"))return bj(n,r);if(!strcmp(k,"merge_sort"))return bm(n,r);if(!strcmp(k,"binary_search"))return bbs(n,r);if(!strcmp(k,"prefix_sum"))return bps(n,r);if(!strcmp(k,"matrix_mul"))return bmm(n,r);if(!strcmp(k,"bfs"))return bbfs(n,r);if(!strcmp(k,"dijkstra"))return bdij(n,r);if(!strcmp(k,"union_find"))return buf(n,r);if(!strcmp(k,"mandelbrot"))return bman(n,r);if(!strcmp(k,"dynamic_array"))return bva(n,r);if(!strcmp(k,"linked_list"))return bll(n,r);if(!strcmp(k,"queue_ring"))return bqr(n,r);if(!strcmp(k,"hash_table"))return bht(n,r);if(!strcmp(k,"binary_heap"))return bbh(n,r);if(!strcmp(k,"bst"))return bbst(n,r);if(!strcmp(k,"trie"))return btr(n,r);return 64;}
int main(int ac,char**av){const char*k=ac>1?av[1]:"integer50";uint64_t n=ac>2?strtoull(av[2],0,10):ds(k);int r=ac>3?atoi(av[3]):7;return n&&r>0?run(k,n,r):64;}
